    {
      "name": "MvPolynomial.totalDegree_finsetProd",
      "type": " {R : Type u} {σ : Type u_1} [CommSemiring R] {ι : Type u_3} (s : Finset ι) (f : ι → MvPolynomial σ R) : (s.prod f).totalDegree ≤ ∑ i ∈ s, (f i).totalDegree",
      "module": "Mathlib.Algebra.MvPolynomial.Degrees"
    },
    {
      "name": "MvPolynomial.degreeOf_prod_le",
      "type": " {R : Type u} {σ : Type u_1} [CommSemiring R] {ι : Type u_3} (i : σ) (s : Finset ι) (f : ι → MvPolynomial σ R) : MvPolynomial.degreeOf i (∏ j ∈ s, f j) ≤ ∑ j ∈ s, MvPolynomial.degreeOf i (f j)",
      "module": "Mathlib.Algebra.MvPolynomial.Degrees"
    },
    {
      "name": "MvPolynomial.degrees_prod_le",
      "type": " {R : Type u} {σ : Type u_1} [CommSemiring R] {ι : Type u_3} {s : Finset ι} {f : ι → MvPolynomial σ R} : (∏ i ∈ s, f i).degrees ≤ ∑ i ∈ s, (f i).degrees",
      "module": "Mathlib.Algebra.MvPolynomial.Degrees"
    },
    {
      "name": "MvPolynomial.vars_prod",
      "type": " {R : Type u} {σ : Type u_1} [CommSemiring R] {ι : Type u_3} [DecidableEq σ] {s : Finset ι} (f : ι → MvPolynomial σ R) : (∏ i ∈ s, f i).vars ⊆ s.biUnion fun i => (f i).vars",
      "module": "Mathlib.Algebra.MvPolynomial.Variables"
    },
    {
      "name": "MonomialOrder.degree_prod_le",
      "type": " {σ : Type u_1} {m : MonomialOrder σ} {R : Type u_2} [CommSemiring R] {ι : Type u_3} {P : ι → MvPolynomial σ R} {s : Finset ι} : m.toSyn (m.degree (∏ i ∈ s, P i)) ≤ m.toSyn (∑ i ∈ s, m.degree (P i))",
      "module": "Mathlib.RingTheory.MvPolynomial.MonomialOrder"
    },
    {
      "name": "MvPolynomial.schwartz_zippel_sum_degreeOf",
      "type": " {R : Type u_1} [CommRing R] [IsDomain R] [DecidableEq R] {n : ℕ} {p : MvPolynomial (Fin n) R} (hp : p ≠ 0) (S : Fin n → Finset R) : ↑{x ∈ Fintype.piFinset fun i => S i | (MvPolynomial.eval x) p = 0}.card / ∏ i, ↑(S i).card ≤ ∑ i, ↑(MvPolynomial.degreeOf i p) / ↑(S i).card",
      "module": "Mathlib.Algebra.MvPolynomial.SchwartzZippel"
    },
    {
      "name": "MvPolynomial.schwartz_zippel_sup_sum",
      "type": " {R : Type u_1} [CommRing R] [IsDomain R] [DecidableEq R] {n : ℕ} {p : MvPolynomial (Fin n) R} (hp : p ≠ 0) (S : Fin n → Finset R) : ↑{x ∈ Fintype.piFinset fun i => S i | (MvPolynomial.eval x) p = 0}.card / ∏ i, ↑(S i).card ≤ p.support.sup fun s => ∑ i, ↑(s i) / ↑(S i).card",
      "module": "Mathlib.Algebra.MvPolynomial.SchwartzZippel"
    },
    {
      "name": "Polynomial.homogenize_finsetProd",
      "type": " {R : Type u_1} [CommSemiring R] {ι : Type u_2} {s : Finset ι} {p : ι → Polynomial R} {n : ι → ℕ} (h : ∀ i ∈ s, (p i).natDegree ≤ n i) : (∏ i ∈ s, p i).homogenize (∑ i ∈ s, n i) = ∏ i ∈ s, (p i).homogenize (n i)",
      "module": "Mathlib.Algebra.Polynomial.Homogenize"
    }
  ]
}
